    "html": "<section class=\"lab-megafone-a\" style=\"height:100%;min-height:520px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;position:relative;box-sizing:border-box;background:#FFFFFF;font-family:'Inter',sans-serif;color:#14110D;\"><style>.lab-megafone-a h1,.lab-megafone-a h1 *{white-space:normal !important;overflow-wrap:break-word;word-break:normal;} .lab-megafone-a{overflow:hidden;}</style>\n  <style>\n    .lab-megafone-a *{box-sizing:border-box;}\n    .lab-megafone-a .mga-wrap{max-width:1100px;margin:0 auto;padding:28px;width:100%;display:flex;flex-direction:column;align-items:center;text-align:center;position:relative;z-index:3;}\n    .lab-megafone-a .mga-eyebrow{font-family:'Gridlite',monospace;font-size:clamp(10px,1.1vw,12px);letter-spacing:.22em;text-transform:uppercase;color:#6b6258;margin:0 0 22px;display:inline-flex;align-items:center;gap:10px;}\n    .lab-megafone-a .mga-eyebrow .mga-dot{width:9px;height:9px;background:#7CF067;border-radius:50%;display:inline-block;flex:none;box-shadow:0 0 0 3px rgba(124,240,103,.22);}\n    .lab-megafone-a h1{font-family:'Atelier',sans-serif;font-weight:800;font-size:clamp(38px,6.4vw,74px);line-height:1.03;letter-spacing:-.02em;margin:0;max-width:14ch;color:#14110D;}\n    .lab-megafone-a h1 .mga-key{position:relative;white-space:nowrap;color:#D262B2;}\n    .lab-megafone-a h1 .mga-key::after{content:\"\";position:absolute;left:-2px;right:-2px;bottom:.08em;height:.10em;background:#D262B2;border-radius:2px;opacity:.55;}\n    .lab-megafone-a p.mga-sub{font-size:clamp(15px,1.7vw,19px);line-height:1.55;color:#4a443c;max-width:54ch;margin:24px 0 0;}\n    .lab-megafone-a .mga-ctas{display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-top:36px;}\n    .lab-megafone-a a.mga-btn{display:inline-flex;align-items:center;gap:10px;font-family:'Inter',sans-serif;font-weight:600;font-size:15px;text-decoration:none;padding:15px 26px;border-radius:999px;transition:transform .18s ease,box-shadow .18s ease,background .18s ease;pointer-events:auto;}\n    .lab-megafone-a a.mga-primary{background:#D262B2;color:#FFFFFF;box-shadow:0 10px 26px -10px rgba(210,98,178,.7);}\n    .lab-megafone-a a.mga-primary img{width:20px;height:20px;border-radius:5px;display:block;}\n    .lab-megafone-a a.mga-primary:hover{transform:translateY(-2px);box-shadow:0 16px 34px -10px rgba(210,98,178,.78);}\n    .lab-megafone-a a.mga-primary .mga-arrow{transition:transform .18s ease;}\n    .lab-megafone-a a.mga-primary:hover .mga-arrow{transform:translateX(4px);}\n    .lab-megafone-a a.mga-secondary{background:transparent;color:#14110D;border:1.5px solid rgba(20,17,13,.18);}\n    .lab-megafone-a a.mga-secondary:hover{transform:translateY(-2px);border-color:#14110D;}\n    .lab-megafone-a .mga-megafone{position:absolute;top:-34px;left:-30px;width:clamp(220px,30vw,360px);mix-blend-mode:multiply;pointer-events:none;z-index:1;animation:megafone-a-floaty 7s ease-in-out infinite;}\n    .lab-megafone-a .mga-star1{position:absolute;top:46px;right:8%;width:clamp(40px,5vw,66px);pointer-events:none;z-index:2;animation:megafone-a-starspin 16s linear infinite;}\n    .lab-megafone-a .mga-star2{position:absolute;bottom:60px;left:11%;width:clamp(28px,3.6vw,46px);pointer-events:none;z-index:2;animation:megafone-a-floaty2 6s ease-in-out infinite;}\n    .lab-megafone-a .mga-greenform{position:absolute;bottom:42px;right:13%;width:18px;height:18px;background:#7CF067;border-radius:50%;pointer-events:none;z-index:2;box-shadow:0 0 0 5px rgba(124,240,103,.16);animation:megafone-a-pop 5s ease-in-out infinite;}\n    @keyframes megafone-a-floaty{0%,100%{transform:translateY(0) rotate(-2deg);}50%{transform:translateY(-14px) rotate(0deg);}}\n    @keyframes megafone-a-floaty2{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}\n    @keyframes megafone-a-starspin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}\n    @keyframes megafone-a-pop{0%,100%{transform:scale(1);opacity:.9;}50%{transform:scale(1.22);opacity:1;}}\n    @media(max-width:640px){\n      .lab-megafone-a .mga-megafone{top:-18px;left:-44px;opacity:.9;}\n      .lab-megafone-a .mga-star1{top:14px;right:4%;}\n      .lab-megafone-a a.mga-btn{padding:14px 22px;}\n    }\n  </style>\n\n  <img class=\"mga-megafone\" src=\"/v2/elements/colagem-megafone-mao-estrela-rosa.png\" alt=\"\" aria-hidden=\"true\">\n  <img class=\"mga-star1\" src=\"/v2/elements/grafismo-estrela-rosa-01.png\" alt=\"\" aria-hidden=\"true\">\n  <img class=\"mga-star2\" src=\"/v2/elements/grafismo-estrela-rosa-01.png\" alt=\"\" aria-hidden=\"true\">\n  <span class=\"mga-greenform\" aria-hidden=\"true\"></span>\n\n  <div class=\"mga-wrap\">\n    <span class=\"mga-eyebrow\"><span class=\"mga-dot\"></span>Agencia nativa do mercado cripto · desde 2020</span>\n    <h1>Criatividade que <span class=\"mga-key\">move o mercado cripto</span>.</h1>\n    <p class=\"mga-sub\">Conteudo, estrategia e lancamentos para marcas web3 que querem ser referencia, nao so mais ruido no feed.</p>\n    <div class=\"mga-ctas\">\n      <a class=\"mga-btn mga-primary\" href=\"https://calendly.com/madureira-kaleidosdigital/30min\" target=\"_blank\" rel=\"noopener\">\n        <img src=\"/v2/calendly-icon.webp\" alt=\"\">\n        Consultoria gratis\n        <span class=\"mga-arrow\" aria-hidden=\"true\">&rarr;</span>\n      </a>\n      <a class=\"mga-btn mga-secondary\" href=\"/cases\">Ver cases</a>\n    </div>\n  </div>\n</section>"
