    "html": "<section class=\"lab-olho-a\" style=\"height:100%;min-height:520px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;position:relative;box-sizing:border-box;background:#FFFFFF;font-family:'Inter',sans-serif;\"><style>.lab-olho-a h1,.lab-olho-a h1 *{white-space:normal !important;overflow-wrap:break-word;word-break:normal;} .lab-olho-a{overflow:hidden;}</style>\n  <style>\n    .lab-olho-a *{box-sizing:border-box;}\n    .lab-olho-a .olho-a-bg{position:absolute;inset:0;background-image:url('/v2/elements/elemento-olho-halftone-pb.png');background-size:cover;background-position:center;background-repeat:no-repeat;filter:grayscale(1) contrast(1.05);opacity:0.16;pointer-events:none;z-index:0;}\n    .lab-olho-a .olho-a-vignette{position:absolute;inset:0;background:radial-gradient(ellipse 70% 70% at 50% 48%, rgba(255,255,255,0.55) 0%, rgba(255,255,255,0.82) 55%, #FFFFFF 100%);pointer-events:none;z-index:1;}\n    .lab-olho-a .olho-a-wrap{position:relative;z-index:3;width:100%;max-width:1100px;margin:0 auto;padding:28px;text-align:center;display:flex;flex-direction:column;align-items:center;}\n    .lab-olho-a .olho-a-eyebrow{display:inline-flex;align-items:center;gap:9px;font-family:'Gridlite',monospace;font-size:clamp(10px,1.1vw,12px);letter-spacing:0.16em;text-transform:uppercase;color:#14110D;background:#FFFFFF;border:1.5px solid #14110D;padding:7px 15px;border-radius:100px;margin-bottom:30px;}\n    .lab-olho-a .olho-a-dot{width:8px;height:8px;border-radius:50%;background:#7CF067;flex:none;}\n    .lab-olho-a h1{font-family:'Atelier',sans-serif;font-weight:800;color:#14110D;font-size:clamp(38px,6.6vw,82px);line-height:0.98;letter-spacing:-0.025em;margin:0 0 26px;max-width:14ch;}\n    .lab-olho-a h1 .olho-a-hl{color:#D262B2;position:relative;white-space:nowrap;}\n    .lab-olho-a p.olho-a-sub{font-family:'Inter',sans-serif;font-size:clamp(15px,1.85vw,21px);line-height:1.55;color:#4a443c;margin:0 0 38px;max-width:60ch;}\n    .lab-olho-a .olho-a-ctas{display:flex;flex-wrap:wrap;gap:14px;justify-content:center;align-items:center;}\n    .lab-olho-a a.olho-a-btn{display:inline-flex;align-items:center;gap:10px;text-decoration:none;font-family:'Inter',sans-serif;font-weight:700;font-size:clamp(14px,1.5vw,16px);padding:15px 26px;border-radius:100px;transition:transform .18s ease, box-shadow .18s ease, background .18s ease;}\n    .lab-olho-a a.olho-a-primary{background:#D262B2;color:#FFFFFF;box-shadow:0 8px 24px rgba(210,98,178,0.32);}\n    .lab-olho-a a.olho-a-primary:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(210,98,178,0.42);}\n    .lab-olho-a a.olho-a-primary img{width:20px;height:20px;border-radius:50%;object-fit:cover;}\n    .lab-olho-a a.olho-a-primary .olho-a-arrow{transition:transform .18s ease;}\n    .lab-olho-a a.olho-a-primary:hover .olho-a-arrow{transform:translateX(4px);}\n    .lab-olho-a a.olho-a-secondary{background:#FFFFFF;color:#14110D;border:1.5px solid #14110D;}\n    .lab-olho-a a.olho-a-secondary:hover{background:#14110D;color:#FFFFFF;transform:translateY(-2px);}\n    .lab-olho-a .olho-a-star{position:absolute;z-index:2;pointer-events:none;width:46px;height:46px;}\n    .lab-olho-a .olho-a-star.s1{top:16%;left:9%;animation:olho-a-starspin 16s linear infinite;opacity:.9;}\n    .lab-olho-a .olho-a-star.s2{bottom:18%;right:10%;width:34px;height:34px;animation:olho-a-floaty 7s ease-in-out infinite;opacity:.85;}\n    @keyframes olho-a-starspin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}\n    @keyframes olho-a-floaty{0%,100%{transform:translateY(0);}50%{transform:translateY(-12px);}}\n    @media (max-width:620px){\n      .lab-olho-a .olho-a-wrap{padding:24px 20px;}\n      .lab-olho-a h1 .olho-a-hl{white-space:normal;}\n      .lab-olho-a a.olho-a-btn{flex:1 1 auto;justify-content:center;}\n      .lab-olho-a .olho-a-star.s1{left:4%;top:8%;width:34px;height:34px;}\n      .lab-olho-a .olho-a-star.s2{right:5%;}\n    }\n  </style>\n\n  <div class=\"olho-a-bg\" aria-hidden=\"true\"></div>\n  <div class=\"olho-a-vignette\" aria-hidden=\"true\"></div>\n\n  <img class=\"olho-a-star s1\" src=\"/v2/elements/grafismo-estrela-rosa-01.png\" alt=\"\" aria-hidden=\"true\">\n  <img class=\"olho-a-star s2\" src=\"/v2/elements/grafismo-estrela-verde-01.png\" alt=\"\" aria-hidden=\"true\">\n\n  <div class=\"olho-a-wrap\">\n    <span class=\"olho-a-eyebrow\"><span class=\"olho-a-dot\"></span>Agencia nativa do mercado cripto · desde 2020</span>\n    <h1>Criatividade que <span class=\"olho-a-hl\">move o mercado cripto</span>.</h1>\n    <p class=\"olho-a-sub\">Conteudo, estrategia e lancamentos para marcas web3 que querem ser referencia, nao so mais ruido no feed.</p>\n    <div class=\"olho-a-ctas\">\n      <a class=\"olho-a-btn olho-a-primary\" href=\"https://calendly.com/madureira-kaleidosdigital/30min\" target=\"_blank\" rel=\"noopener\">\n        <img src=\"/v2/calendly-icon.webp\" alt=\"\">\n        Consultoria gratis\n        <span class=\"olho-a-arrow\" aria-hidden=\"true\">&rarr;</span>\n      </a>\n      <a class=\"olho-a-btn olho-a-secondary\" href=\"/cases\">Ver cases</a>\n    </div>\n  </div>\n</section>"
